// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title SearchIndexer
 * @notice On-chain search index with HTTP oracle integration and audit logging
 * @dev Uses oracle callbacks for off-chain index synchronization
 */
contract SearchIndexer is Ownable, ReentrancyGuard {
    struct IndexEntry {
        bytes32 contentHash;
        uint256 timestamp;
        address submitter;
        uint16 contentLength;
        bytes metadata;
    }

    struct AuditLog {
        address actor;
        bytes4 action;
        uint256 timestamp;
        bytes32 targetHash;
    }

    struct OracleRequest {
        bytes rawHeaders;
        bytes body;
        uint16 declaredContentLength;
        bool processed;
    }

    mapping(bytes32 => IndexEntry) public index;
    AuditLog[] public auditLogs;
    mapping(uint256 => OracleRequest) public pendingRequests;
    mapping(address => bool) public authorizedOracles;

    uint256 public requestNonce;
    uint256 public constant MAX_HEADER_SIZE = 8192;
    uint256 public constant MAX_BODY_SIZE = 65535;

    event IndexUpdated(bytes32 indexed contentHash, address indexed submitter);
    event OracleRequestCreated(uint256 indexed requestId, bytes32 contentHash);
    event AuditEvent(address indexed actor, bytes4 action, bytes32 targetHash);

    modifier onlyOracle() {
        require(authorizedOracles[msg.sender], "Not authorized oracle");
        _;
    }

    constructor() Ownable(msg.sender) {}

    function authorizeOracle(address oracle) external onlyOwner {
        authorizedOracles[oracle] = true;
        _logAudit(msg.sender, bytes4(keccak256("AUTHORIZE")), bytes32(uint256(uint160(oracle))));
    }

    function submitDocument(bytes32 contentHash, bytes calldata metadata) external nonReentrant {
        require(contentHash != bytes32(0), "Invalid hash");
        require(metadata.length <= 1024, "Metadata too large");

        index[contentHash] = IndexEntry({
            contentHash: contentHash,
            timestamp: block.timestamp,
            submitter: msg.sender,
            contentLength: uint16(metadata.length),
            metadata: metadata
        });

        _logAudit(msg.sender, bytes4(keccak256("SUBMIT")), contentHash);
        emit IndexUpdated(contentHash, msg.sender);
    }

    /**
     * @notice Creates an oracle request to sync with off-chain HTTP index service
     * @param headers Raw HTTP headers for the oracle to forward
     * @param body Request body content
     * @param contentHash The document hash being synced
     */
    function requestIndexSync(
        bytes calldata headers,
        bytes calldata body,
        bytes32 contentHash
    ) external nonReentrant {
        require(index[contentHash].submitter == msg.sender, "Not document owner");
        require(headers.length <= MAX_HEADER_SIZE, "Headers too large");
        require(body.length <= MAX_BODY_SIZE, "Body too large");

        uint16 declaredLength = _parseContentLength(headers);

        uint256 reqId = requestNonce++;
        pendingRequests[reqId] = OracleRequest({
            rawHeaders: headers,
            body: body,
            declaredContentLength: declaredLength,
            processed: false
        });

        _logAudit(msg.sender, bytes4(keccak256("SYNC_REQ")), contentHash);
        emit OracleRequestCreated(reqId, contentHash);
    }

    /**
     * @notice Oracle callback to fulfill sync request
     * @dev Validates content-length matches body before forwarding
     */
    function fulfillSyncRequest(uint256 requestId, bytes calldata response) external onlyOracle nonReentrant {
        OracleRequest storage req = pendingRequests[requestId];
        require(!req.processed, "Already processed");

        // Validate the request integrity before oracle processes it
        // Content-Length header must match actual body length
        require(_validateRequestIntegrity(req), "Request integrity check failed");

        req.processed = true;
        _logAudit(msg.sender, bytes4(keccak256("FULFILL")), bytes32(requestId));
    }

    /**
     * @dev Parses Content-Length from raw HTTP headers
     * @notice Extracts the FIRST Content-Length value found
     */
    function _parseContentLength(bytes calldata headers) internal pure returns (uint16) {
        bytes memory clHeader = "Content-Length: ";
        uint256 headerLen = clHeader.length;

        for (uint256 i = 0; i <= headers.length - headerLen; i++) {
            bool found = true;
            for (uint256 j = 0; j < headerLen; j++) {
                // Case-insensitive comparison for header name
                bytes1 a = headers[i + j];
                bytes1 b = clHeader[j];
                if (a != b && _toLower(a) != _toLower(b)) {
                    found = false;
                    break;
                }
            }
            if (found) {
                return _parseUint16(headers, i + headerLen);
            }
        }
        return 0;
    }

    /**
     * @dev Validates that declared content-length matches actual body
     * @notice This prevents HTTP request smuggling by ensuring consistency
     */
    function _validateRequestIntegrity(OracleRequest storage req) internal view returns (bool) {
        // If no Content-Length declared, allow (chunked encoding)
        if (req.declaredContentLength == 0) {
            return true;
        }
        // Validate: declared length must match actual body length
        // Using uint16 comparison - declaredContentLength is uint16
        return req.declaredContentLength == uint16(req.body.length);
    }

    function _parseUint16(bytes calldata data, uint256 offset) internal pure returns (uint16) {
        uint16 result = 0;
        for (uint256 i = offset; i < data.length; i++) {
            bytes1 c = data[i];
            if (c >= 0x30 && c <= 0x39) {
                result = result * 10 + uint16(uint8(c) - 48);
            } else {
                break;
            }
        }
        return result;
    }

    function _toLower(bytes1 b) internal pure returns (bytes1) {
        if (b >= 0x41 && b <= 0x5A) {
            return bytes1(uint8(b) + 32);
        }
        return b;
    }

    function _logAudit(address actor, bytes4 action, bytes32 target) internal {
        auditLogs.push(AuditLog({
            actor: actor,
            action: action,
            timestamp: block.timestamp,
            targetHash: target
        }));
        emit AuditEvent(actor, action, target);
    }

    function getAuditLogCount() external view returns (uint256) {
        return auditLogs.length;
    }

    function getAuditLogRange(uint256 start, uint256 end) external view returns (AuditLog[] memory) {
        require(end <= auditLogs.length && start < end, "Invalid range");
        AuditLog[] memory logs = new AuditLog[](end - start);
        for (uint256 i = start; i < end; i++) {
            logs[i - start] = auditLogs[i];
        }
        return logs;
    }
}
